<script>
import fileDownload from "js-file-download";
export default {
  name: "VueBasicJiami",

  data() {
    return {
        showshow:false,
      items: [
        {
          img: require("./image/main/1.jpg"),
          name: "prediction-1",
        },
        {
          img: require("./image/main/2.jpg"),
          name: "prediction-2",
        },
        {
          img: require("./image/main/3.jpg"),
          name: "prediction-3",
        },
      ],
      items_2:[
        {
        img: "./image/main/4.jpg",
        name: "prediction-4",
      }
      ],
      information:"",
    };
  },

  mounted() {},

  methods: {
    produce() {
      let data = new FormData();
      data.append("data", this.information);
      this.$axios
        .post("http://127.0.0.1:5000/predict", data, {
          responseType: "blob",
        })
        .then((res) => {
            console.log("fileDownload前面一行语句")
          fileDownload(res.data, "hello.mp3");
        });
            // var that = this;
            // setTimeout(function() {
            //     that.showshow=true
            // },
            // 2000);
    },
  },
};
</script>

